<section class="customer-card p-0 overflow-hidden"><div class="customer-order-tabs"><a class="<?php echo e(!$selectedStatus?'active':''); ?>" href="<?php echo e(route('customer.orders')); ?>">All (<?php echo e($statusCounts->sum()); ?>)</a><?php $__currentLoopData = ['pending'=>'Pending','accepted'=>'Confirmed','processing'=>'Processing','shipped'=>'On The Way','delivered'=>'Delivered','cancelled'=>'Cancelled']; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $status=>$label): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><a class="<?php echo e($selectedStatus===$status?'active':''); ?>" href="<?php echo e(route('customer.orders',['status'=>$status])); ?>"><?php echo e($label); ?> (<?php echo e($statusCounts[$status]); ?>)</a><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></div><div class="customer-order-list"><?php $__empty_1 = true; $__currentLoopData = $orders; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $order): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); $__empty_1 = false; ?><article class="customer-order-row"><div><b>Order ID <span class="text-primary">#<?php echo e($order->order_number); ?></span></b><small>Placed on <?php echo e($order->created_at->format('d M, Y h:i A')); ?></small></div><span>QTY: <?php echo e(rtrim(rtrim(number_format($order->items->sum('quantity'),2),'0'),'.')); ?></span><span>Amount: <b>$<?php echo e(number_format($order->total,2)); ?></b></span><span class="customer-status"><?php echo e($order->status); ?></span><a href="<?php echo e(route('customer.orders.show',$order)); ?>">View Details</a></article><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); if ($__empty_1): ?><div class="customer-empty"><i class="bi bi-bag-x"></i><p>No <?php echo e($selectedStatus ? $selectedStatus.' ' : ''); ?>orders found.</p></div><?php endif; ?></div><div class="px-4 pb-3"><?php echo e($orders->links()); ?></div></section>
